// Robot results browser: a sortable task table plus a detail panel with every teleoperation
// attempt and autonomous trial. Reads window.LAB_DATA (static/data/lab.js) and
// window.ROBOT_DATA (static/data/robot.js, generated by scripts/build_robot_data.py).
(function () {
  var root = document.getElementById("results-browser");
  if (!root || !window.LAB_DATA || !window.ROBOT_DATA) return;

  var MODELS = ["pi_all", "pi_ind", "sol6.1", "dream1"];
  var NAMES = window.LAB_DATA.APPROACHES;
  var PAIRS = window.LAB_DATA.PAIRS;
  var tasks = window.LAB_DATA.TASKS.map(function (t) {
    var r = window.ROBOT_DATA.tasks[t.id];
    var pair = PAIRS.find(function (p) { return p[0] === t.verb && p[1] === t.object; });
    return Object.assign({}, t, {
      robot: r,
      freq: pair ? pair[2] : 0,
      teleopRate: r.teleop.rate / 100,
      results: MODELS.map(function (m) { return r.models[m].succ; })
    });
  });
  var selected = "pick-wafer";
  var PUBLIC = document.body.hasAttribute("data-public");  // set by scripts/build_public.py

  // The tooltip lives outside <body> so the page's CSS zoom doesn't offset it from the cursor.
  var tip = document.createElement("div");
  tip.className = "rb-tip";
  document.documentElement.appendChild(tip);
  function showTip(html, ev) {
    tip.innerHTML = html;
    tip.style.opacity = 1;
    tip.style.left = Math.min(ev.clientX + 14, window.innerWidth - 290) + "px";
    tip.style.top = (ev.clientY + 14) + "px";
  }
  function hideTip() { tip.style.opacity = 0; }

  function esc(s) {
    return String(s).replace(/[&<>"]/g, function (c) {
      return {"&": "&amp;", "<": "&lt;", ">": "&gt;", "\"": "&quot;"}[c];
    });
  }
  function cell(rate, text) {
    var alpha = Math.max(0.06, rate * 0.85).toFixed(2);
    return '<span class="rb-cell" style="background:rgba(49,116,193,' + alpha + ');color:' +
      (rate > 0.6 ? "#fff" : "#222") + '">' + text + "</span>";
  }

  // Professor's rule: show a successful trial's recording if one exists, else a failed one.
  // Every evaluation trial was recorded, so there is always a clip to point to.
  function robotVideo(t) {
    var supp = t.video ? " · Supp. Video " + t.video.success : "";
    for (var i = 0; i < MODELS.length; i++) {
      var ok = t.robot.models[MODELS[i]].trials.find(function (x) { return x[1]; });
      if (ok) return {kind: "success", label: "Success · " + NAMES[i] + ", trial " + ok[0] + supp, source: ok[3]};
    }
    var first = t.robot.models[MODELS[0]].trials[0];
    return {kind: "failure", label: "Failure · " + NAMES[0] + ", trial " + first[0] + supp, source: first[3]};
  }

  function renderTable() {
    var key = document.getElementById("rb-sort").value;
    var rows = tasks.slice().sort(function (x, y) {
      if (key === "freq") return y.freq - x.freq;
      if (key === "teleop") return y.teleopRate - x.teleopRate;
      return y.results[+key] - x.results[+key];
    });
    document.getElementById("rb-body").innerHTML = rows.map(function (t) {
      return '<tr tabindex="0" data-id="' + t.id + '" class="' + (t.id === selected ? "is-selected" : "") + '">' +
        '<td class="rb-task">' + esc(t.name) + "</td><td>" + t.freq.toLocaleString() + "</td>" +
        "<td>" + cell(t.teleopRate, Math.round(t.teleopRate * 100) + "%") + "</td>" +
        t.results.map(function (r) { return "<td>" + cell(r / 10, r + "/10") + "</td>"; }).join("") + "</tr>";
    }).join("");
    var totals = MODELS.map(function (m, i) {
      return tasks.reduce(function (s, t) { return s + t.results[i]; }, 0);
    });
    document.getElementById("rb-foot").innerHTML = '<tr><td class="rb-task"><strong>Total</strong></td><td></td><td></td>' +
      totals.map(function (n) { return "<td><strong>" + n + "/100</strong></td>"; }).join("") + "</tr>";
    root.querySelectorAll("#rb-body tr").forEach(function (tr) {
      tr.addEventListener("click", function () { select(tr.dataset.id, true); });
      tr.addEventListener("keydown", function (e) {
        if (e.key === "Enter" || e.key === " ") { e.preventDefault(); select(tr.dataset.id, false); }
      });
    });
    renderDetail();
  }

  function renderDetail() {
    var t = tasks.find(function (x) { return x.id === selected; });
    var v = robotVideo(t), tel = t.robot.teleop;
    var seqTip = {s: "success", f: "failure", p: "not labeled yet"};
    var attempts = tel.seq.split("").map(function (c, i) {
      return '<span class="sq ' + c + '" data-tip="Attempt ' + (i + 1) + ": " + seqTip[c] + '"></span>';
    }).join("");
    var trials = MODELS.map(function (m, i) {
      var r = t.robot.models[m];
      var squares = r.trials.map(function (x) {
        return '<span class="sq ' + (x[1] ? "s" : "f") + '" data-tip="Trial ' + x[0] + ": " +
          (x[1] ? "success" : "failure") + ", " + x[2] + " s" +
          (x[3] ? "<br><span class='rb-src'>" + esc(x[3]) + "</span>" : "") + '"></span>';
      }).join("");
      var time = r.median ? "median " + r.median.toFixed(1) + " s" : "no successes";
      var cost = m === "sol6.1" ? " · $" + t.robot.sol_cost.toFixed(2) : "";
      return '<div class="trial-row"><div class="trial-head"><span>' + NAMES[i] + '</span><span class="trial-meta"><strong>' +
        r.succ + "/" + r.n + "</strong> · " + time + cost + '</span></div><span class="strip">' + squares + "</span></div>";
    }).join("");

    var clip = PUBLIC ? "" :
      '<div class="media-placeholder is-' + v.kind + '"><span>' + esc(v.label) + "</span></div>" +
      '<p class="rb-src" style="margin:0.25rem 0 0.75rem;">' + esc(v.source) + "</p>";
    document.getElementById("rb-detail").innerHTML = clip +
      '<h4 class="title is-5" style="margin-bottom:0.3rem;">' + esc(t.name) + "</h4>" +
      '<p style="font-size:0.88rem;">' + esc(t.desc) + '<br><span style="color:#666;">Success: ' + esc(t.success) + "</span></p>" +
      '<div style="margin:0.6rem 0;">' +
        '<span class="chip">Seen ' + t.freq.toLocaleString() + "× in footage</span>" +
        '<span class="chip">Teleop ' + tel.succ + "/" + (tel.succ + tel.fail) + " (" + Math.round(tel.rate) +
          "%, 95% CI " + Math.round(tel.lo) + "–" + Math.round(tel.hi) + "%)</span>" +
        '<span class="chip">' + tel.mean.toFixed(1) + " ± " + tel.sd.toFixed(1) + " s per success</span>" +
      "</div>" +
      '<div class="rb-label">Every teleoperation attempt, in order</div>' +
      '<div class="strip">' + attempts + "</div>" +
      '<div class="rb-label">Autonomous trials (hover for ' + (PUBLIC ? "times" : "time and recording") + ")</div>" + trials;

    root.querySelectorAll("#rb-detail [data-tip]").forEach(function (el) {
      el.addEventListener("mousemove", function (ev) { showTip(el.dataset.tip, ev); });
      el.addEventListener("click", function (ev) { showTip(el.dataset.tip, ev); }); // touch screens
      el.addEventListener("mouseleave", hideTip);
    });
  }

  function select(id, scroll) {
    selected = id;
    renderTable();
    hideTip();
    // On phones the detail panel sits below the table, so bring it into view.
    if (scroll && window.matchMedia("(max-width: 768px)").matches) {
      document.getElementById("rb-detail").scrollIntoView({behavior: "smooth", block: "start"});
    }
  }
  window.addEventListener("scroll", hideTip, {passive: true});
  window.ResultsBrowser = {select: function (id) { select(id, false); }};  // used by pair-map.js
  document.getElementById("rb-sort").addEventListener("change", renderTable);
  renderTable();
})();
